Translate("deDE", "razorfen-kraul", {
	title = "Der Kral von Razorfen",
	aliases = { "der Kral", "Kral" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Kral von Razorfen ist der große Dornenbau der {link:quilboar}Stacheleber{/link} am Südrand des {link:the-barrens}Brachlands{/link}, nahe der Grenze zu {link:thousand-needles}Tausend Nadeln{/link}. Er ist ein Labyrinth aus Gräben, Tunneln und Brücken, verwoben durch Dornenranken, so gewaltig, dass sie sich wie Mauern um ihn erheben. Die Stacheleber halten ihn für heilig. Er ist auch eine Festung, und in der Gegenwart ist er der Sitz einer alten Vettel, die das südliche Brachland zu ihrem eigenen machen will.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Vor zehntausend Jahren, im {link:war-of-the-ancients}Krieg der Ahnen{/link}, erhob sich der Halbgott {red:agamaggan}Agamaggan{/red}, um gegen die {link:burning-legion}Brennende Legion{/link} zu kämpfen. Der große Eber fiel im Kampf. Sein Körper drückte das Land flach, wo er starb, und sein Blut sickerte in die Erde. Wo es hinfiel, wuchsen verdrehte Dornentürme empor. Die {link:quilboar}Stacheleber{/link}, die sich seine Kinder nennen, ließen sich zwischen den Dornen nieder und nannten sie Razorfen. Der Kral ist eine ihrer größten Festungen.

Die {link:night-elves}Nachtelfen{/link} erinnern sich an Agamaggan als ein reines und großzügiges Wesen. Ihre Druiden können nicht sagen, warum das Land um seine Ruhestätte so verdorben ist, noch warum die Dornen eine eigene Verderbnis zu verbreiten scheinen.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Die alte Vettel {link:charlga-razorflank}Charlga Razorflank{/link} herrscht über den Kral. Sie ist eine Meisterin der Erdmagie, und sie sammelt ein Heer. Unter den Stachelebern des südlichen Brachlands wurden die {link:tauren}Tauren{/link} aus Ländern vertrieben, die sie seit Generationen gehalten hatten, und sie haben es nicht vergessen. Aus dem Kral kamen die drei Anführer der {link:razormane-quilboar}Grimmhauer{/link}, die vom {link:blackthorn-ridge}Schwarzdorngrat{/link} aus die Versorgungswege von {link:the-crossroads}Crossroads{/link} ausbluten ließen.

Schlimmeres geht als Gerücht um. Ein Brief, den man der Vettel abnahm, trägt das Siegel der {link:scourge}Geißel{/link}. Ein Gesandter der Untoten wartet vor den {link:razorfen-downs}Hügeln von Razorfen{/link}, dem anderen großen Bau im Osten, und bietet ihr das {link:the-barrens}Brachland{/link} und mehr im Tausch für freie Hand. Ihre Krieger sprechen bereits von neuen Verbündeten.

Wenige Außenstehende haben den Kral betreten und sind wieder herausgekommen. Ein Druide der {link:night-elves}Nachtelfen{/link} namens {link:heralath-fallowbrook}Heralath{/link} und ein {link:dwarves}Zwerg{/link} der {link:explorers-league}Forscherliga{/link} wurden als Gefangene hierher geschleppt. Ein Goblinhändler kam wegen seltener Knollen und wurde gefangen. Nun hat der Alarm {link:thalanaar}Thalanaar{/link}, {link:thunder-bluff}Thunder Bluff{/link} und sogar {link:undercity}Undercity{/link} erreicht.]=],
		},
		{
			title = "Im Kral",
			text = [=[• {b}Die Gräben.{/b} Gewundene Pfade unter den Dornen, wo Blaublattknollen wachsen und Tierbändiger ihre Eber halten.
• {b}Die Halle des Oberherrn.{/b} {link:overlord-ramtusk}Oberherr Ramtusk{/link} befehligt hier das Kriegsheer, mit dem {link:death-speaker-jargba}Todessprecher Jargba{/link} und dem Propheten {link:aggem-thorncurse}Aggem Thorncurse{/link} in der Nähe.
• {b}Die Fledermaushöhlen.{/b} Tiefe Tunnel voller Kralfledermäuse. In ihren dunkelsten Tiefen jagt ein bleiches Tier, das nie das Tageslicht gesehen hat.
• {b}Der Pferch.{/b} Ein Tunnel, versiegelt durch eine Barriere aus {link:quilboar}Stacheleber{/link}-Magie, in dem {link:agathelos-the-raging}Agathelos der Tobende{/link} gehalten wird.
• {b}Die Hütte der Vettel.{/b} Charlgas Behausung steht hoch oben auf einer Rampe aus Dornen. Darunter, in einer kleinen Hütte, liegen die Gefangenen des Krals.]=],
		},
	},
})

Translate("deDE", "charlga-razorflank", {
	title = "Charlga Razorflank",
	subtitle = "Die Vettel des Krals",
	found = [=[Ihre Hütte auf den Dornen, in den Tiefen des Krals von Razorfen]=],
	hint = [=[Steigt zur Hütte der Vettel hinauf, die über den Kral von Razorfen herrscht.]=],
	allegiance = "Stacheleber der Razorfen",
	aliases = { "Razorflank", "die Vettel des Krals", "die Vettel" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Charlga Razorflank ist die Vettel des Krals von Razorfen, eine betagte Stacheleberin und eine mächtige Meisterin der Erdmagie. Sie herrscht über den großen Bau von einer Hütte hoch zwischen seinen Dornen. Unter ihr sind die {link:quilboar}Stacheleber{/link} des Krals kühn geworden. Sie überfallen rivalisierende Stämme und die Dörfer der {link:horde}Horde{/link}, nehmen Gefangene und rüsten zum Krieg. Sie nennt die Länder um den {link:razorfen-kraul}Kral{/link} ihr Eigen, und sie behandelt jeden Außenstehenden als Dieb.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Charlga ist die aufstrebende Macht des südlichen Brachlands. Druiden der {link:night-elves}Nachtelfen{/link} fürchten, dass sich die Verderbnis der Dornen von ihrem Herrschaftsgebiet aus ausbreiten wird. Die {link:tauren}Tauren{/link} von {link:thunder-bluff}Thunder Bluff{/link} machen ihr Volk dafür verantwortlich, dass sie aus ihrem heiligen Land vertrieben wurden. Und die {link:scourge}Geißel{/link} hat sie als Verbündete auf {link:kalimdor}Kalimdor{/link} gesucht. Ob sie ihr Angebot angenommen hat, kann niemand außerhalb des Krals sagen.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie nahm den {link:razorfen-kraul}Kral{/link} ein und sammelte die {link:quilboar}Stacheleber{/link} unter ihrer Herrschaft.
• Ihre Krieger nahmen den Druiden {link:heralath-fallowbrook}Heralath{/link} und den {link:dwarves}Zwerg{/link} Henrig Lonebrow gefangen.
• Sie erhielt Briefe von {link:ambassador-malcin}Malcin{/link}, dem Gesandten der {link:scourge}Geißel{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Die Warnung",
			hint = "Bringt die Warnung eines toten Zwergs nach Thalanaar.",
			text = [=[Henrig Lonebrow entkam dem {link:razorfen-kraul}Kral{/link} mit einer Warnung für {link:falfindel-waywarder}Falfindel Waywarder{/link} in {link:thalanaar}Thalanaar{/link}: Die Vettel wiegle ihre Diener auf, und ihre Macht wachse von Tag zu Tag. Der {link:dwarves}Zwerg{/link} starb, bevor er sie überbringen konnte. Sein Tagebuch tat die Arbeit für ihn. Falfindel schickte andere aus, um das Leben der Vettel zu beenden, und hoffte, dass sein Volk nach ihrem Tod erfahren könnte, was die Ruhestätte Agamaggans verdorben hatte.]=],
		},
		{
			title = "Ein rachsüchtiges Schicksal",
			hint = "Antwortet dem Tauren-Ältesten, der nicht vergeben kann.",
			text = [=[{red:auld-stonespire}Auld Stonespire{/red} aus {link:thunder-bluff}Thunder Bluff{/link} ehrt {link:cairne-bloodhoof}Cairne Bloodhoof{/link} dafür, dass er die {link:tauren}Tauren{/link} geeint hat, doch er kann jenen nicht vergeben, die sein Volk aus dem südlichen {link:the-barrens}Brachland{/link} vertrieben. Er verlangte das Herz der Vettel. Als es zu ihm kam, sagte er, die {link:quilboar}Stacheleber{/link} des Krals kennten nun den Schmerz seines Volkes.]=],
		},
		{
			title = "Der Brief des Gesandten",
			hint = "Sucht nach dem, was die Vettel bei sich trägt.",
			text = [=[Bei der Vettel fand man eine kleine Schriftrolle. Sie war von {link:ambassador-malcin}Botschafter Malcin{/link} unterzeichnet, der ihr das {link:the-barrens}Brachland{/link} und mehr versprach, wenn man ihm dort freie Hand ließe. {link:varimathras}Varimathras{/link} erkannte das Siegel sofort. Er urteilte, dass die Vettel noch nicht nachgegeben hatte, vielleicht weil sie spürte, dass das Brachland unter solchen Verbündeten nie wirklich ihres sein würde.]=],
		},
	},
	mentions = {
		{ text = "Lonebrows Tagebuch" },
		{ text = "Ein unheiliges Bündnis" },
	},
	bonds = {
		{ id = "overlord-ramtusk", name = "Oberherr Ramtusk", note = "befehligt ihre Krieger" },
		{ id = "heralath-fallowbrook", name = "Heralath Fallowbrook", note = "ihr Gefangener" },
		{ id = "varimathras", name = "Varimathras", note = "las den Brief, den sie verwahrte" },
	},
})

Translate("deDE", "overlord-ramtusk", {
	title = "Oberherr Ramtusk",
	subtitle = "Kriegsherr des Krals",
	found = [=[Die Kriegshalle des Krals von Razorfen, flankiert von seinen Wachen]=],
