	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Oberherr Ramtusk befehligt die Krieger des Krals von Razorfen. Er ist ein alter und massiger {link:quilboar}Stacheleber{/link}. Man sagt, seine Haut trage die Narben von Kämpfen mit {link:centaurs}Zentauren{/link}, {link:harpies}Harpyien{/link}, {link:orcs}Orcs{/link} und {link:tauren}Tauren{/link} und das Alter habe ihn kein bisschen verlangsamt. Zwei Stachelhaut-Wachen stehen an seiner Seite und würden für ihn sterben. Er zieht mit dem Namen Agamaggans auf den Lippen in die Schlacht.]=],
