			title = "Bedeutung",
			text = [=[Ramtusk ist das Schwert der Vettel. Das Heer, das sie sammelt, gehorcht ihm, und es sind seine Krieger, die ihren Krieg ins {link:the-barrens}Brachland{/link} tragen werden, wenn niemand sie zuvor aufhält.]=],
		},
		{ title = "Taten", text = "• Er führt das Kriegsheer des Krals." },
	},
	bonds = {
		{ id = "charlga-razorflank", name = "Charlga Razorflank", note = "seine Herrin" },
		{ id = "death-speaker-jargba", name = "Todessprecher Jargba", note = "hält seine Krieger gehorsam" },
	},
})

Translate("deDE", "death-speaker-jargba", {
