		{ id = "charlga-razorflank", name = "Charlga Razorflank", note = "die Vettel, der er dient" },
		{ id = "aggem-thorncurse", name = "Aggem Thorncurse", note = "ein Gefährte vom Totenkopf" },
	},
})

Translate("deDE", "aggem-thorncurse", {
	title = "Aggem Thorncurse",
	subtitle = "Prophet des Totenkopfs",
	found = "Die Hallen des Krals von Razorfen",
	hint = "Stellt Euch dem Propheten des Krals, der Ebergeister ruft.",
