	aliases = { "Thorncurse" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Aggem Thorncurse ist ein Prophet des Totenkopfs. Unter den Stachelebern werden die größten Schamanen Propheten Agamaggans genannt. Sie rufen die Macht ihres Ahnen an, um Ebergeister an ihre Seite zu beschwören, so wie andere Schamanen Geisterwölfe rufen. Aggem tut dies zur Verteidigung des Krals, und ein Geistereber kämpft an seiner Seite, wenn er bedroht wird.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Aggem trägt den Namen des Ebergottes und den Titel des dunklen Ordens zugleich. In ihm sind der alte Schamanismus der {link:quilboar}Stacheleber{/link} und das neue Glaubensbekenntnis des Totenkopfs eins geworden.]=],
		},
		{
			title = "Taten",
			text = [=[• Er ruft Geistereber, um den {link:razorfen-kraul}Kral{/link} zu verteidigen.]=],
		},
	},
	bonds = {
		{ id = "death-speaker-jargba", name = "Todessprecher Jargba", note = "ein Gefährte vom Totenkopf" },
		{ id = "charlga-razorflank", name = "Charlga Razorflank", note = "die Vettel, der er dient" },
	},
})

Translate("deDE", "roogug", {
	title = "Roogug",
	subtitle = "Geomant des Krals",
	found = "Die ersten Gräben des Krals von Razorfen",
	hint = [=[Stellt Euch dem Geomanten, der die ersten Gräben des Krals bewacht.]=],
	allegiance = "Stacheleber der Razorfen",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Roogug ist ein Geomant des Krals von Razorfen, der die ersten Gräben hinter seinem Tor hütet. Wie {link:charlga-razorflank}die Vettel{/link}, der er dient, schöpft er aus der Macht der Erde. Er schleudert Blitze und ruft einen lebenden Stein, der an seiner Seite kämpft. Er trägt auch eine Phiole Phlogiston bei sich, eines seltenen feurigen Stoffes, den Schmiede der {link:alliance}Allianz{/link} wie der {link:horde}Horde{/link} für das Schmieden gehärteter Rüstungen suchen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Roogug ist der erste der Mystiker der Vettel, dem ein Eindringling begegnet.]=],
		},
		{ title = "Taten", text = "• Er bewacht die westlichen Gräben mit der Magie der Erde." },
	},
	mentions = {
		{ text = "Feuergehärtete Rüstung" },
		{ text = "Brutale Rüstung" },
	},
	bonds = {
		{ id = "charlga-razorflank", name = "Charlga Razorflank", note = "die Vettel, der er dient" },
	},
})

Translate("deDE", "agathelos-the-raging", {
	title = "Agathelos der Tobende",
	subtitle = "Der eingepferchte Eber",
	found = [=[Ein versiegelter Tunnel jenseits der Fledermaushöhlen des Krals von Razorfen]=],
	hint = [=[Sucht den großen Eber, den die Stacheleber hinter ihrer Barriere halten.]=],
	allegiance = "Keine",
	aliases = { "Agathelos" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Agathelos der Tobende ist ein kolossaler gepanzerter Eber, der in einem Tunnel des Krals von Razorfen gehalten wird. {link:quilboar}Stacheleber{/link}-Wärter halten ihn hinter einer Barriere aus Magie. Für ein Volk, das einen großen Eber seinen Gott nennt, ist ein solches Tier kein gewöhnliches: Man sagt, sie sähen einen mächtigen Eber als Geschenk Agamaggans. Man sagt auch, er sei mit dem Dung der Kralfledermäuse gefüttert worden, der ihn in den Wahnsinn treibt und noch stärker macht, und der {link:death-s-head}Totenkopf{/link} wolle ihn auf seine Feinde loslassen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Agathelos ist eine Waffe, die bereitgemacht wird, ein lebendes Echo des Gottes, den {link:razorfen-kraul}der Kral{/link} verehrt.]=],
		},
		{ title = "Taten", text = "• Er tobt in seinem Pferch und wächst in seiner Wut." },
	},
	bonds = {
		{ id = "charlga-razorflank", name = "Charlga Razorflank", note = "seine Hüterin" },
	},
})

Translate("deDE", "blind-hunter", {
	title = "Blinder Jäger",
	subtitle = "Die bleiche Fledermaus der Tiefe",
	found = "Die dunkelsten Fledermaushöhlen des Krals von Razorfen",
	hint = [=[Durchsucht die tiefsten Fledermaushöhlen des Krals nach einem bleichen Jäger.]=],
	allegiance = "Keine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Blinde Jäger ist eine große bleiche Fledermaus, die in den tiefsten Höhlen des Krals von Razorfen umgeht. Sie wird selten gesehen, selbst von den Stachelebern. Sie lebt dort, wohin kein Licht dringt, und scheint keine Augen zu brauchen. Die geringeren Kralfledermäuse nisten näher an den Tunneleingängen. Ihr Dung ist so selten, dass die {link:royal-apothecary-society}Königliche Apothekervereinigung{/link} von {link:undercity}Undercity{/link} danach geschickt hat.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Der Blinde Jäger ist der älteste Schrecken der dunklen Orte des Krals.]=],
		},
		{ title = "Taten", text = "• Er jagt in den Tiefen der Fledermaushöhlen." },
	},
	mentions = {
		{ text = "Weg damit, weg damit, Guano!" },
	},
})

Translate("deDE", "earthcaller-halmgar", {
	title = "Erdrufer Halmgar",
	subtitle = "Erdruferin des Krals",
	found = [=[Jenseits der Kriegshalle des Krals von Razorfen, hinter den Holzbrücken]=],
	hint = [=[Sucht die seltene Erdruferin, die über die Brücken des Krals wandert.]=],
	allegiance = "Stacheleber der Razorfen",
	aliases = { "Halmgar" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Erdrufer Halmgar ist eine Mystikerin der {link:quilboar}Stacheleber{/link} im {link:razorfen-kraul}Kral{/link} von Razorfen, eine der Erdformerinnen, die {link:charlga-razorflank}die Vettel{/link} um sich gesammelt hat. Man findet sie nicht oft. Wenn doch, ruft sie Blitze auf ihre Feinde herab, bindet sie mit einem Totem an den Boden und beschwört lebenden Stein, um sie zu zermalmen. Die Erdrufer sind der Grund, warum die Dornen des Krals so schwer zu stürmen sind.]=],
