			text = [=[Halmgar zeigt die Tiefe der Erdmagie, über die {link:charlga-razorflank}die Vettel{/link} gebietet. Wo die Mystiker der Vettel wandeln, kämpft selbst der Boden des Krals für die {link:quilboar}Stacheleber{/link}.]=],
		},
		{ title = "Taten", text = "• Sie bewacht die Pfade jenseits der Kriegshalle." },
	},
	bonds = {
		{ id = "charlga-razorflank", name = "Charlga Razorflank", note = "die Vettel, der sie dient" },
	},
})

Translate("deDE", "willix-the-importer", {
	title = "Willix der Importeur",
	subtitle = "Goblinunternehmer",
	found = [=[Eine Hütte unterhalb der Rampe der Vettel, im Kral von Razorfen]=],
	hint = [=[Sucht den Goblin-Gefangenen, der in den Tiefen des Krals festgehalten wird.]=],
	allegiance = "Ratchet · Steamwheedle-Kartell",
	aliases = { "Willix" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Willix ist ein Goblinhändler aus {link:ratchet}Ratchet{/link}, stets auf ein Kupferstück aus. Er hörte, dass Mebok Mizzyrix gut für die seltenen Knollen zahlte, die im {link:razorfen-kraul}Kral{/link} wachsen, und hielt es für leichte Arbeit. Die {link:quilboar}Stacheleber{/link} fingen ihn. Er wurde so lange festgehalten, dass er vergaß, wann er zuletzt den Himmel gesehen hatte. Selbst als Gefangener behielt er den Gewinn im Auge: Die Knollen in den Gräben, sagt er, seien Gold, das nur darauf warte, ausgegraben zu werden.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Willix ist der Beweis, dass {link:razorfen-kraul}der Kral{/link} ebenso ein Gefängnis wie eine Festung ist.]=],
		},
	},
	chapters = {
		{
			title = "Aus den Dornen",
			hint = "Führt den Goblin-Gefangenen aus dem Kral.",
			text = [=[Willix wurde durch die Gräben hinaus und durch das Dornengestrüpp hinauf geführt und schrie bei jedem {link:quilboar}Stacheleber{/link}, der angriff, Warnungen. An der Hütte der Vettel vorbei verfluchte er sie als verdammte alte Vettel. Endlich stand er frei, kam zu Atem und machte sich auf den Weg nach {link:ratchet}Ratchet{/link}.]=],
		},
	},
	mentions = {
		{ text = "Blaublattknollen" },
	},
	bonds = {
		{ id = "heralath-fallowbrook", name = "Heralath Fallowbrook", note = "ein Mitgefangener" },
	},
})

Translate("deDE", "heralath-fallowbrook", {
	title = "Heralath Fallowbrook",
	subtitle = "Druide von Darnassus",
	found = "Eine Gefangenenhütte in den Tiefen des Krals von Razorfen",
	hint = [=[Sucht den verwundeten Nachtelfen, der im Kral gefangen gehalten wird.]=],
	allegiance = "Nachtelfen · Darnassus",
	aliases = { "Heralath" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Heralath Fallowbrook ist ein Druide der {link:night-elves}Nachtelfen{/link}, der ins südliche {link:the-barrens}Brachland{/link} kam, um die Wahrheit über den gefallenen Ebergott zu erfahren. Er glaubte, dass der große Schädel der Ebenen den Ort kennzeichnete, an dem Agamaggan fiel, und sein Volk wollte wissen, warum die Ruhestätte eines so reinen Wesens verdorben war. Die {link:quilboar}Stacheleber{/link} nahmen ihn gefangen, peitschten ihn aus und warfen ihn in eine Hütte im {link:razorfen-kraul}Kral{/link}. Dort teilte er seine Zelle mit dem {link:dwarves}Zwerg{/link} {red:henrig-lonebrow}Henrig Lonebrow{/red} und vertraute ihm eine Warnung für {link:falfindel-waywarder}Falfindel Waywarder{/link} an.]=],
